'use strict';
/**
 * loom/templates/system-scaffold.js — "build another system on the fly."
 * comp_id: nexus.loom.templates.system-scaffold
 * UUID: nexus-loom-scaffold-v1-0000-2026-0702-jamesbrooks-001
 * Phase: 145 (this session)
 *
 * The generalized version of what Phase 131 did specifically for LOOM.
 * One list of operations goes in; five real, working projections come
 * out, generated in the exact order you specified:
 *
 *   1. component/seam/hook/wire  — registered into LOOM (via LoomDriver),
 *                                  not just written as a file
 *   2. CLI                        — cli/index.js, first, per your order
 *   3. API                        — api/index.js, second
 *   4. file maps + configs        — registry-components.js, mirrors the
 *                                  real pattern already used by
 *                                  architect/idearium/ollama's own files
 *   5. interaction contract       — interaction-contract.json, shape
 *                                  copied from idearium's real, live one
 *                                  (id/version/namespace/port/transport/
 *                                  resources), not invented
 *
 *   UI is explicitly NOT generated. scaffoldSystem() has no UI-producing
 *   code path at all — not "disabled," not "TODO," genuinely absent —
 *   because generating even a stub UI here would violate the one rule
 *   you set for this whole build order.
 *
 * Why one operations list drives four outputs instead of four hand-
 * written files: this is Architect's own stated principle applied
 * generatively — "the spec IS the system, code is a projection of the
 * spec." Here the operations list is that spec-equivalent. Change an
 * operation once, regenerate, all four projections stay consistent —
 * the alternative (hand-maintaining CLI commands, API routes, and a
 * contract file separately) is exactly how they drift apart.
 */
const fs = require('fs');
const path = require('path');
const { LoomDriver } = require('../schema/index');

/**
 * Operation shape (the one thing you define per system):
 *   { id, verb, method, apiPath, params: [], description }
 * `verb` -> CLI command (e.g. "list", "create"). `method`+`apiPath` -> API route.
 */
function _validateOperations(operations) {
  if (!Array.isArray(operations) || operations.length === 0) {
    throw new Error('[scaffold] operations must be a non-empty array');
  }
  for (const op of operations) {
    for (const key of ['id', 'verb', 'method', 'apiPath']) {
      if (!op[key]) throw new Error(`[scaffold] operation missing required key "${key}": ${JSON.stringify(op)}`);
    }
  }
}

// ── Projection 2: CLI (first) ───────────────────────────────────────────────
function _renderCli(systemName, operations) {
  const cases = operations.map(op => `    case '${op.verb}': {
      const result = await dispatch('${op.id}', args);
      console.log(JSON.stringify(result, null, 2));
      break;
    }`).join('\n');

  return `'use strict';
/**
 * ${systemName}/cli/index.js — generated by loom/templates/system-scaffold.js
 * Do not hand-edit the verb list below; regenerate from the operations
 * list instead, or CLI/API drift apart the way phase 64/hook-registry did.
 *
 * Usage: node ${systemName}/cli/index.js <verb> [--key value ...]
 */
const { dispatch } = require('../api/index');

function _parseArgs(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i++) {
    if (argv[i].startsWith('--')) {
      const key = argv[i].slice(2);
      const val = argv[i + 1] && !argv[i + 1].startsWith('--') ? argv[++i] : true;
      out[key] = val;
    }
  }
  return out;
}

async function main() {
  const [verb, ...rest] = process.argv.slice(2);
  const args = _parseArgs(rest);
  switch (verb) {
${cases}
    default:
      console.error(\`Unknown verb: \${verb}\`);
      console.error('Available: ${operations.map(o => o.verb).join(', ')}');
      process.exit(1);
  }
}

if (require.main === module) main();
module.exports = { main };
`;
}

// ── Projection 3: API (second) — same dispatch() the CLI calls ─────────────
function _renderApi(systemName, operations, port) {
  const dispatchCases = operations.map(op => `    case '${op.id}': return { ok: true, op: '${op.id}', args, note: 'stub handler \u2014 replace with real logic' };`).join('\n');
  // \u00a7BUG FOUND BY DOGFOODING (clearglass-accounts, this session): naive
  // startsWith() route matching in declaration order means a shorter
  // path like /api/accounts always shadows a longer, more specific one
  // like /api/accounts/usage \u2014 the longer route is dead code, always
  // caught by the shorter check first. Fix: sort longest-path-first so
  // the most specific match always wins. This was a real bug in
  // generated output, not a hypothetical \u2014 caught the moment a real
  // system with overlapping paths was actually built and run.
  const sorted = [...operations].sort((a, b) => b.apiPath.length - a.apiPath.length);
  // \u00a7BUG FOUND BY DOGFOODING (nexus-healer, 2026-07-14): a second,
  // distinct route bug, not the ordering one above \u2014 startsWith() also
  // can't match a :param segment against a real value at all.
  // '/proposals/:id/evaluate' compared against a real request URL like
  // '/proposals/abc123/evaluate' never matches, because the literal
  // string ':id' isn't in the real URL. The longest-path-first fix above
  // never exercised this \u2014 its own test suite never gave it an
  // operation with a :param in its apiPath. Found the moment a real
  // resource-style API (proposals addressed by id) was actually
  // scaffolded and run, same as the first bug. Fix: real segment-based
  // matching, :param treated as a wildcard and its value extracted into
  // args, same convention this codebase's other real routers use.
  const routes = sorted.map(op => {
    const paramNames = (op.apiPath.match(/:([a-zA-Z_]+)/g) || []).map(p => p.slice(1));
    return `  if (req.method === '${op.method}' && _matchPath('${op.apiPath}', u.pathname, ${JSON.stringify(paramNames)}, args)) {
    const result = await dispatch('${op.id}', args);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result));
    return;
  }`;
  }).join('\n');

  return `'use strict';
/**
 * ${systemName}/api/index.js \u2014 generated by loom/templates/system-scaffold.js
 * dispatch() is the single source both CLI and API call \u2014 one place to
 * implement real behavior, not two surfaces that quietly diverge.
 * Routes below are ordered longest-path-first \u2014 see comment in the
 * generator (system-scaffold.js) for why that ordering is load-bearing.
 * Route matching is real segment matching, not startsWith() \u2014 a :param
 * segment matches any value there and is extracted into args.
 */
const http = require('http');
const { URL } = require('url');

const PORT = parseInt(process.env.${systemName.toUpperCase().replace(/-/g, '_')}_PORT || '${port}', 10);

function _matchPath(pattern, pathname, paramNames, args) {
  const patSegs = pattern.split('/').filter(Boolean);
  const reqSegs = pathname.split('/').filter(Boolean);
  if (reqSegs.length < patSegs.length) return false;
  for (let i = 0; i < patSegs.length; i++) {
    if (patSegs[i].startsWith(':')) {
      args[patSegs[i].slice(1)] = reqSegs[i];
    } else if (patSegs[i] !== reqSegs[i]) {
      return false;
    }
  }
  return true;
}

async function dispatch(opId, args) {
  switch (opId) {
${dispatchCases}
    default: return { ok: false, error: \`unknown operation: \${opId}\` };
  }
}

// §FIXED 2026-07-14 — found while wiring nexus-healer's real propose/
// evaluate logic, not hypothetical: args was built ONLY from URL search
// params, every single POST body was silently ignored. Every scaffolded
// system with a create/action-style POST endpoint (propose a healer
// hypothesis, submit anything with a real payload) had this same gap —
// same root-cause shape as the real bug found in cortex/boot.js's
// POST /api/recall earlier this session (query never read from the
// body). Fixed at the generator, not just nexus-healer's one file, so
// every future scaffolded system gets this for free.
function _readBody(req) {
  return new Promise((resolve) => {
    if (req.method !== 'POST' && req.method !== 'PUT' && req.method !== 'PATCH') { resolve({}); return; }
    let data = '';
    req.on('data', c => data += c);
    req.on('end', () => { try { resolve(JSON.parse(data || '{}')); } catch (_) { resolve({}); } });
    req.on('error', () => resolve({}));
  });
}

function createServer() {
  return http.createServer(async (req, res) => {
    const u = new URL(req.url, \`http://\${req.headers.host || 'localhost'}\`);
    const body = await _readBody(req);
    const args = { ...Object.fromEntries(u.searchParams), ...body };
${routes}
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ ok: false, error: 'no matching route' }));
  });
}

if (require.main === module) {
  createServer().listen(PORT, () => console.log(\`${systemName} API on :\${PORT}\`));
}

module.exports = { dispatch, createServer, PORT };
`;
}

// ── Projection 4: registry-components.js — real pattern, not invented ──────
function _renderRegistryComponents(systemName, operations) {
  const entries = operations.map(op =>
    `  _c('${op.id}', '${op.method}', '${op.apiPath}', ${JSON.stringify(op.description || op.id)}${op.params ? `, { params: ${JSON.stringify(op.params)} }` : ''}),`
  ).join('\n');

  return `'use strict';
/**
 * ${systemName}/registry-components.js — generated by loom/templates/system-scaffold.js
 * comp_id: nexus.${systemName}.registry
 * Same shape as architect/registry-components.js and idearium/registry-components.js.
 */
const V = '0.1.0'; const NS = '${systemName}';
function _c(id, method, path, desc, opts = {}) {
  return {
    id: \`\${NS}.\${id}\`, namespace: NS, name: id, version: V,
    route: { method, path }, description: desc,
    params: opts.params || [], tags: [NS, ...(opts.tags || [])],
    permissions: opts.permissions || ['system'],
  };
}
module.exports = [
${entries}
];
`;
}

// ── Projection 5: interaction-contract.json — copied shape from idearium ───
function _renderInteractionContract(systemName, operations, port) {
  const resources = {};
  for (const op of operations) {
    resources[op.id] = {
      endpoints: {
        [op.verb]: { method: op.method, path: op.apiPath, ...(op.params ? { params: op.params } : {}) },
      },
    };
  }
  return {
    id: `${systemName}-v1`,
    version: '0.1.0',
    namespace: systemName,
    port,
    transport: {
      http: `http://127.0.0.1:${port}`,
      guardian: 'http://127.0.0.1:7820',
    },
    resources,
  };
}

// ── Projection 6: config.js — real pattern from versionium/ollama/intelligence ──
function _renderConfig(systemName, port) {
  const envPrefix = systemName.toUpperCase().replace(/-/g, '_');
  return `'use strict';
/**
 * ${systemName}/config.js — generated by loom/templates/system-scaffold.js
 * Matches ollama/config.js, intelligence/config.js, versionium/config.js's
 * established pattern: one file, every real value env-overridable.
 */
const path = require('path');

module.exports = {
  PORT: parseInt(process.env.${envPrefix}_PORT || '${port}', 10),
  ORCH_URL: process.env.ORCHESTRATOR_URL || 'http://127.0.0.1:9000',
  DATA_DIR: process.env.${envPrefix}_DATA_DIR || path.join(__dirname, '..', 'data', '${systemName}'),
  SYSTEM_ID: '${systemName}',
  VERSION:   '0.1.0',
};
`;
}

// ── Projection 7: event-taxonomy.js — ET1 shape (lib/event-taxonomy-pattern.js) ──
function _renderEventTaxonomy(systemName, operations) {
  const upper = systemName.toUpperCase().replace(/-/g, '_');
  const entries = operations.map(op => {
    const key = `${upper}_${op.id.toUpperCase().replace(/[^A-Z0-9]/g, '_')}_INVOKED`;
    return `  ${key}: {
    description: ${JSON.stringify(`The '${op.id}' operation was invoked — ${op.description || 'seeded stub, fill in what actually happened'}.`)},
    payloadShape: ${JSON.stringify(op.params || [])},
    severity: 'info',
  },`;
  }).join('\n');

  return `'use strict';
// ${systemName}/event-taxonomy.js — generated by loom/templates/system-scaffold.js
// Conforms to lib/event-taxonomy-pattern.js's ET1 shape. One entry seeded per
// operation — real event names, stub descriptions. Fill in as the system's
// real emit()/jaaDB.insert('event_log', ...) calls land; this file documents
// what's real, not what's planned.

module.exports = Object.freeze({
${entries}
});
`;
}

// ── Projection 8: real .spec (not .spec.md) — nexus-system-foundation shape ──
function _renderSpec(systemName, operations, port, purpose) {
  const routeLines = operations.map(op =>
    `      - { method: ${op.method}, path: ${op.apiPath}, description: ${JSON.stringify(op.description || op.id)} }`
  ).join('\n');
  const nowIso = new Date().toISOString();
  return `spec:
  meta:
    name:        ${systemName}
    version:     0.1.0
    foundation:  nexus-system-foundation@1.1.0
    status:      scaffolded
    uuid:        nexus-${systemName}-v1-0000-${nowIso.slice(0,10).replace(/-/g,'')}-jamesbrooks-scaffold
    purpose: >
      ${purpose || '(not specified — fill in before this system does anything real)'}
    generated_by: loom/templates/system-scaffold.js
    generated_at: ${nowIso}

  core:
    schemas: {}
    axioms: []
    constants: {}

  events:
    taxonomy_file: ${systemName}/event-taxonomy.js

  routes:
    external:
${routeLines}

  handshake:
    components: []   # populated once registry-components.js entries are real, not stub

  compartment:
    tier: system
    kind: cos_process
    modules: []       # each module gets its own logical-compartment entry — see modules/<name>/<name>.spec

  ui:
    type: none
    hotswap: false

  history:
    - { ts: "${nowIso}", change: "scaffolded via loom/templates/system-scaffold.js, no real logic yet" }

  gaps: []

  tests: []
`;
}

// ── Projection 9: tool-index.js / command-index.js — per-system aggregates ──
function _renderCommandIndex(systemName, operations) {
  const entries = operations.map(op =>
    `  { id: '${systemName}.${op.id}.command', verb: '${op.verb}', route: { method: '${op.method}', path: '${op.apiPath}' } },`
  ).join('\n');
  return `'use strict';
/**
 * ${systemName}/command-index.js — generated by loom/templates/system-scaffold.js
 * Aggregate registry of every .command node this system owns. One entry per
 * operation. Same aggregation role hooks/index.js used to play for hooks —
 * ownership of that pattern is Loom's (§AR1, 2026-09-11 phasemap).
 */
module.exports = [
${entries}
];
`;
}

function _renderToolIndex(systemName) {
  return `'use strict';
/**
 * ${systemName}/tool-index.js — generated by loom/templates/system-scaffold.js
 * Aggregate registry of every .tool node this system owns. Empty at
 * scaffold time — operations produce .command/.route nodes, not .tool
 * nodes; tools are internal utility functions a system declares as it
 * builds them. Add entries as: { id: '${systemName}.<name>.tool', ... }
 */
module.exports = [];
`;
}

// ── Projection 10: capabilities.js — capability -> command routing, enforced ──
function _renderCapabilities(systemName, capabilities, operationIds) {
  const names = Object.keys(capabilities);
  for (const capName of names) {
    const routed = capabilities[capName];
    if (!Array.isArray(routed) || routed.length === 0) {
      throw new Error(`[scaffold] capability "${capName}" routes to 0 commands — |routes(C)| >= 1 is required, not optional`);
    }
    for (const opId of routed) {
      if (!operationIds.includes(opId)) {
        throw new Error(`[scaffold] capability "${capName}" routes to unknown operation id "${opId}"`);
      }
    }
  }
  const entries = names.map(capName =>
    `  { id: '${systemName}.${capName}.capability', routes: ${JSON.stringify(capabilities[capName].map(id => `${systemName}.${id}.command`))} },`
  ).join('\n');
  return `'use strict';
/**
 * ${systemName}/capabilities.js — generated by loom/templates/system-scaffold.js
 * Every capability node here was verified at scaffold time to route to
 * >=1 real command node (the capability_invariant from the 2026-09-11
 * compartment/nodetype phasemap). A capability with 0 routes fails
 * scaffoldSystem() outright, not silently.
 */
module.exports = [
${entries}
];
`;
}

// ── Projection 11: module/component logical-compartment skeletons ──────────
// Per the locked model: system = real COS compartment (handled by cos's own
// archetype/create path, not here). module/component = logical compartment —
// own dir, own living .spec, own event contract, no spawned process.
function _renderCompartmentSpec(systemName, tier, name, parentPath) {
  const nowIso = new Date().toISOString();
  return `spec:
  meta:
    name:        ${name}
    tier:        ${tier}
    system:      ${systemName}
    path:        ${parentPath}
    version:     0.1.0
    status:      scaffolded
    generated_by: loom/templates/system-scaffold.js
    generated_at: ${nowIso}
    purpose: >
      (not specified — fill in before this ${tier} does anything real)

  compartment:
    tier: ${tier}
    kind: logical        # never a spawned OS process — see locked_model in
                          # the 2026-09-11 compartment/nodetype phasemap
    inputs: []
    outputs: []

  capabilities: []
  commands: []
  tools: []

  history:
    - { ts: "${nowIso}", change: "scaffolded, no real logic yet" }

  gaps: []
`;
}

function _renderEventContract(systemName, tier, name) {
  return JSON.stringify({
    id: `${systemName}.${name}`,
    tier,
    version: '0.1.0',
    emits: [],
    handles: [],
  }, null, 2) + '\n';
}

function _scaffoldModulesAndComponents(sysDir, systemName, modules) {
  const written = [];
  for (const mod of modules || []) {
    const modDir = path.join(sysDir, 'modules', mod.name);
    fs.mkdirSync(modDir, { recursive: true });
    const modSpecPath = path.join(modDir, `${mod.name}.spec`);
    fs.writeFileSync(modSpecPath, _renderCompartmentSpec(systemName, 'module', mod.name, `${systemName}/modules/${mod.name}`));
    written.push(modSpecPath);
    const modContractPath = path.join(modDir, 'event-contract.json');
    fs.writeFileSync(modContractPath, _renderEventContract(systemName, 'module', mod.name));
    written.push(modContractPath);

    for (const comp of mod.components || []) {
      const compDir = path.join(modDir, 'components', comp.name);
      fs.mkdirSync(compDir, { recursive: true });
      const compSpecPath = path.join(compDir, `${comp.name}.spec`);
      fs.writeFileSync(compSpecPath, _renderCompartmentSpec(systemName, 'component', comp.name, `${systemName}/modules/${mod.name}/components/${comp.name}`));
      written.push(compSpecPath);
      const compContractPath = path.join(compDir, 'event-contract.json');
      fs.writeFileSync(compContractPath, _renderEventContract(systemName, 'component', comp.name));
      written.push(compContractPath);
    }
  }
  return written;
}

/**
 * -> { written: [...paths], registered: {component, hooks} }
 *
 * Writes all projections to disk under outDir/<name>/ (+ data/<name>/
 * sibling to outDir for failures/invariant), and registers the system as
 * a real LOOM component with one hook per operation, wired nowhere yet
 * (wiring is Phase 3's job, per the Lattice L3 note — a fresh system
 * starts with hooks, not wires, exactly like your real "164 hooks
 * replayed, 0 live wires" today).
 *
 * `modules` (optional): [{ name, components: [{ name }, ...] }, ...] —
 * each gets a logical-compartment skeleton (own dir, own living .spec,
 * own event-contract.json), never a spawned process — see locked_model
 * in the 2026-09-11 compartment/nodetype phasemap.
 *
 * `capabilities` (optional): { capName: [operationId, ...] } — each must
 * route to >=1 real operation id, checked before anything is written
 * (capability_invariant, |routes(C)| >= 1). A capability with 0 routes
 * throws, not warns.
 */
function scaffoldSystem(name, { port, purpose = '', operations, outDir, dataDir = null, modules = [], capabilities = {} } = {}) {
  if (!name || !/^[a-z][a-z0-9-]*$/.test(name)) {
    throw new Error('[scaffold] name must be lowercase, start with a letter, e.g. "my-system"');
  }
  if (!port) throw new Error('[scaffold] port is required');
  _validateOperations(operations);
  if (!outDir) throw new Error('[scaffold] outDir is required');

  // Fail before writing anything — capability_invariant is checked up
  // front, not after files are already on disk.
  const operationIds = operations.map(op => op.id);
  for (const [capName, routed] of Object.entries(capabilities)) {
    if (!Array.isArray(routed) || routed.length === 0) {
      throw new Error(`[scaffold] capability "${capName}" routes to 0 commands — |routes(C)| >= 1 is required`);
    }
    for (const opId of routed) {
      if (!operationIds.includes(opId)) {
        throw new Error(`[scaffold] capability "${capName}" routes to unknown operation id "${opId}"`);
      }
    }
  }

  const sysDir = path.join(outDir, name);
  const dirs = ['cli', 'api', 'docs', 'spec'];
  for (const d of dirs) fs.mkdirSync(path.join(sysDir, d), { recursive: true });

  // Own data directory, sibling to outDir — matches versionium/ollama's
  // real precedent (data/<system>/{failures,invariant}), not reusing
  // another system's shared tables. Distinct from `dataDir` below, which
  // is LoomDriver's OWN registry storage location — conflating the two
  // would put a system's failures/invariant folders inside Loom's
  // internal registry directory whenever a caller happened to pass one.
  const dataRoot = path.join(outDir, 'data', name);
  for (const sub of ['failures', 'invariant']) {
    fs.mkdirSync(path.join(dataRoot, sub), { recursive: true });
  }

  const written = [];
  function _write(rel, content) {
    const full = path.join(sysDir, rel);
    fs.writeFileSync(full, content);
    written.push(full);
  }

  // Projection 1 — real .spec (nexus-system-foundation shape), not .spec.md
  _write('spec/' + name + '.spec', _renderSpec(name, operations, port, purpose));

  // Projection 2 — CLI (first)
  _write('cli/index.js', _renderCli(name, operations));

  // Projection 3 — API (second)
  _write('api/index.js', _renderApi(name, operations, port));

  // Projection 4 — file maps + configs
  _write('registry-components.js', _renderRegistryComponents(name, operations));

  // Projection 5 — interaction contract
  _write('interaction-contract.json', JSON.stringify(_renderInteractionContract(name, operations, port), null, 2));

  // Projection 6 — config.js
  _write('config.js', _renderConfig(name, port));

  // Projection 7 — event-taxonomy.js (ET1 shape)
  _write('event-taxonomy.js', _renderEventTaxonomy(name, operations));

  // Projection 8 — tool-index.js / command-index.js
  _write('command-index.js', _renderCommandIndex(name, operations));
  _write('tool-index.js', _renderToolIndex(name));

  // Projection 9 — capabilities.js, only if any were declared
  if (Object.keys(capabilities).length > 0) {
    _write('capabilities.js', _renderCapabilities(name, capabilities, operationIds));
  }

  // Projection 10 — module/component logical-compartment skeletons
  written.push(..._scaffoldModulesAndComponents(sysDir, name, modules));

  // Register into LOOM's own component/seam/hook/wire registry — dogfooded,
  // same as Warp and LOOM's own agent-suite were.
  const driver = new LoomDriver({ dataDir });
  const compId = `nexus.${name}`;
  const compResult = driver.declare('component', {
    id: compId, namespace: name, name, version: '0.1.0',
    uuid: `nexus-${name}-v1-0000-2026-0702-jamesbrooks-scaffold`,
  });

  const hookResults = [];
  if (compResult.ok) {
    for (const op of operations) {
      const r = driver.declare('hook', {
        id: `${compId}.${op.id}`, component_id: compId, name: op.id,
        type: 'api', direction: 'out',
        uuid: `nexus-${name}-hook-${op.id}-v1-0000-2026-0702-jamesbrooks-scaffold`,
      });
      hookResults.push(r);
    }
  }

  return { written, registered: { component: compResult, hooks: hookResults } };
}

module.exports = { scaffoldSystem };
